// The renderer is generated by report.mjs; only its reviewed script may run.
export const rendererHash = 'fQKtISGScDM18HWz01iGnnmkKCK87Vxf41qTner33p0=';
// 看板折叠：每个维度默认只展示前 5 个主标签，其余折叠，可一键展开/收起。
const FOLD_LIMIT = 5;
const foldCss = `
#dimensions .card.voc-fold-collapsed .voc-fold-extra{display:none!important}
.voc-fold-last{position:relative}
.voc-fold-collapsed .voc-fold-last::after{content:'';position:absolute;left:0;right:0;bottom:0;height:12px;background:linear-gradient(180deg,rgba(255,255,255,0),#fff);pointer-events:none}
.voc-fold-btn{display:flex;align-items:center;justify-content:center;gap:7px;width:100%;margin-top:9px;padding:8px 10px;border:1px solid color-mix(in srgb,var(--accent,#4879ce) 28%,#dce5f2);background:color-mix(in srgb,var(--accent,#4879ce) 7%,#f7fafd);color:#3d5a86;border-radius:9px;font-size:12px;font-weight:600;transition:background .15s ease,color .15s ease,border-color .15s ease}
.voc-fold-btn:hover{background:color-mix(in srgb,var(--accent,#4879ce) 15%,#f2f6fc);color:#2b4a77;border-color:color-mix(in srgb,var(--accent,#4879ce) 42%,#dce5f2)}
.voc-fold-btn:focus-visible{outline:2px solid var(--accent,#4879ce);outline-offset:1px}
.voc-fold-chev{width:0;height:0;border-left:4.5px solid transparent;border-right:4.5px solid transparent;border-top:5.5px solid currentColor;transition:transform .18s ease;flex:none}
.voc-fold-btn[aria-expanded="true"] .voc-fold-chev{transform:rotate(180deg)}
`;
const foldJs = `
(function(){
 var LIMIT=${FOLD_LIMIT};
 var cards=document.querySelectorAll('#dimensions .card');
 cards.forEach(function(card){
  var groups=[].filter.call(card.children,function(n){return n.classList&&n.classList.contains('tag-group');});
  if(groups.length<=LIMIT)return;
  card.classList.add('voc-fold-collapsed');
  groups.forEach(function(g,i){
   if(i>=LIMIT)g.classList.add('voc-fold-extra');
   if(i===LIMIT-1)g.classList.add('voc-fold-last');
  });
  var btn=document.createElement('button');
  btn.type='button';btn.className='voc-fold-btn';btn.setAttribute('aria-expanded','false');
  var label=document.createElement('span'),chev=document.createElement('span');
  chev.className='voc-fold-chev';chev.setAttribute('aria-hidden','true');
  var sync=function(open){label.textContent=open?'收起标签':'展开全部 '+groups.length+' 个标签';};
  sync(false);
  btn.append(label,chev);
  btn.onclick=function(){
   var open=card.classList.toggle('voc-fold-collapsed')===false;
   btn.setAttribute('aria-expanded',String(open));
   sync(open);
  };
  card.appendChild(btn);
 });
})();
`;
export async function mountReport(frame, html) {
 const doc = new DOMParser().parseFromString(html, 'text/html');
 const scripts = [...doc.querySelectorAll('script')];
 if (scripts.some(s => s.hasAttribute('src')) || doc.querySelector('base, meta[http-equiv="refresh"]')) throw Error('REPORT_SCRIPT');
 const executable = scripts.filter(s => s.type !== 'application/json');
 if (executable.length !== 1) throw Error('REPORT_SCRIPT');
 const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(executable[0].textContent));
 const hash = btoa(String.fromCharCode(...new Uint8Array(bytes)));
 if (![rendererHash, 'ACK+wDQFzOMFU+iHSXMC/KE+Lv04yVfql1PitiY2QMk=', 'u97e7lj3LuYeXUJ9+qIfPF67sg9lEnghZfzDTRSk/U8='].includes(hash)) throw Error('REPORT_SCRIPT');
 // 校验通过后再注入折叠增强，不影响对原始渲染脚本的哈希校验。
 const style = doc.createElement('style');
 style.textContent = foldCss;
 doc.head.appendChild(style);
 const enhance = doc.createElement('script');
 enhance.textContent = foldJs;
 doc.body.appendChild(enhance);
 frame.srcdoc = '<!DOCTYPE html>' + doc.documentElement.outerHTML;
 frame.hidden = false;
}
